class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        int len = 0;
        for (ListNode p = head; p != null; p = p.next) len++;

        // 删的是头节点，没有前驱，必须特判
        if (len == n) return head.next;

        // 走到目标节点的前一个：正数第 len-n 个
        ListNode prev = head;
        for (int i = 1; i < len - n; i++) prev = prev.next;

        prev.next = prev.next.next;
        return head;
    }
}

class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode fast = head, slow = head;

        // 先走 n+1 步：这样 slow 最终会停在前驱位置
        for (int i = 0; i <= n; i++) {
            if (fast == null) return head.next;   // 删的是头节点
            fast = fast.next;
        }

        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }
        slow.next = slow.next.next;
        return head;
    }
}

class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        ListNode fast = dummy, slow = dummy;
        // 从 dummy 出发走 n+1 步
        for (int i = 0; i <= n; i++) fast = fast.next;

        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }
        // 删头时 slow 是 dummy，这段代码同样正确
        slow.next = slow.next.next;

        return dummy.next;
    }
}
